WITH unpacked AS (SELECT id, service, log_ts, level, latency_ms, status_code, payload_json, context['region'] AS region, ARRAY_CONTAINS(MAP_KEYS(context), 'trace') AS has_trace FROM app_logs) SELECT id, service, level, status_code, region, has_trace, CORR(status_code, latency_ms) OVER (PARTITION BY MONTH(log_ts)) AS corr_status_code_latency_ms, SUM(latency_ms) OVER (PARTITION BY MONTH(log_ts), service ORDER BY log_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_latency_ms, FIRST_VALUE(latency_ms) IGNORE NULLS OVER (PARTITION BY DATE_TRUNC('week', log_ts), service ORDER BY log_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_latency_ms, CORR(latency_ms, status_code) OVER (PARTITION BY service) AS corr_latency_ms_status_code, LEAD(latency_ms, 1) OVER (ORDER BY log_ts, id) AS next_latency_ms FROM unpacked;
